# win-bootstrap.ps1 - one-shot setup of the Windows side of the harness.
#
# Run ELEVATED inside the VM, from the bootstrap ISO:
#   powershell -ExecutionPolicy Bypass -File D:\win-bootstrap.ps1
#
# Installs: OpenSSH Server (key auth), RDP, QEMU guest agent.
#
# The authorised key is read from harness.pub next to this script - the ISO
# that 'harness iso' builds carries the key generated by 'winctl auth' on your
# machine. No key material is distributed with the harness itself.

#Requires -RunAsAdministrator
param(
    [string]$KeyFile = (Join-Path $PSScriptRoot 'harness.pub')
)
$ErrorActionPreference = 'Stop'

function Say ($m) { Write-Host "[*] $m" -ForegroundColor Cyan }
function Ok  ($m) { Write-Host "[+] $m" -ForegroundColor Green }
function Warn($m) { Write-Host "[!] $m" -ForegroundColor Yellow }

# ---------------------------------------------------------------- the key
if (-not (Test-Path $KeyFile)) {
    throw "No public key at $KeyFile. Run 'winctl auth' on the Linux side, then 'harness iso', and boot that ISO. Or pass -KeyFile <path>."
}
$HarnessKey = (Get-Content $KeyFile -Raw).Trim()
if ($HarnessKey -notmatch '^(ssh-ed25519|ssh-rsa|ecdsa-sha2-)') {
    throw "$KeyFile does not look like an OpenSSH public key"
}
Ok "Key loaded from $KeyFile"

# ---------------------------------------------------------------- edition
# The RDP *server* is not available on Windows Home. SSH still is, and SSH is
# what most of the work uses, so this is a warning rather than an error.
$ed = (Get-CimInstance Win32_OperatingSystem).Caption
Say "Edition: $ed"
if ($ed -match 'Home') {
    Warn "Windows Home detected - the built-in RDP server is NOT available."
    Warn "SSH will still work; the GUI half of the harness will not."
}

# ------------------------------------------------------------ openssh srv
Say 'Installing OpenSSH Server...'
$cap = Get-WindowsCapability -Online -Name 'OpenSSH.Server*'
if ($cap.State -ne 'Installed') {
    Add-WindowsCapability -Online -Name $cap.Name | Out-Null
    Ok 'OpenSSH.Server installed'
} else { Ok 'OpenSSH.Server already present' }

Set-Service -Name sshd -StartupType Automatic
Start-Service sshd
Ok "sshd running: $((Get-Service sshd).Status)"

# PowerShell as the default remote shell, so `ssh host <cmd>` behaves sanely.
New-ItemProperty -Path 'HKLM:\SOFTWARE\OpenSSH' -Name DefaultShell `
    -Value "$env:SystemRoot\System32\WindowsPowerShell\v1.0\powershell.exe" `
    -PropertyType String -Force | Out-Null
Ok 'Default SSH shell set to PowerShell'

# ------------------------------------------------------------- public key
# NOTE: for members of Administrators, Windows OpenSSH ignores
# ~/.ssh/authorized_keys and reads this file instead - and refuses it unless
# the ACL is locked to SYSTEM + Administrators only. This is the #1 cause of
# silent key-auth failure on Windows.
$akFile = "$env:ProgramData\ssh\administrators_authorized_keys"
if (-not (Test-Path $akFile) -or
    -not (Select-String -Path $akFile -SimpleMatch $HarnessKey -Quiet)) {
    Add-Content -Path $akFile -Value $HarnessKey -Encoding ascii
    Ok 'Harness key added'
} else { Ok 'Harness key already authorised' }

icacls $akFile /inheritance:r /grant 'SYSTEM:F' /grant 'BUILTIN\Administrators:F' | Out-Null
Ok 'ACL locked to SYSTEM + Administrators'

# --------------------------------------------------------------- firewall
if (-not (Get-NetFirewallRule -Name 'sshd-harness' -ErrorAction SilentlyContinue)) {
    New-NetFirewallRule -Name 'sshd-harness' -DisplayName 'OpenSSH Server (harness)' `
        -Enabled True -Direction Inbound -Protocol TCP -Action Allow -LocalPort 22 | Out-Null
}
Ok 'Firewall: TCP/22 allowed'

# -------------------------------------------------------------------- rdp
if ($ed -notmatch 'Home') {
    Set-ItemProperty 'HKLM:\System\CurrentControlSet\Control\Terminal Server' `
        -Name fDenyTSConnections -Value 0
    # NLA on: xfreerdp supports it and it avoids an unauthenticated pre-login
    # surface on a VM that is reachable from the host network.
    Set-ItemProperty 'HKLM:\System\CurrentControlSet\Control\Terminal Server\WinStations\RDP-Tcp' `
        -Name UserAuthentication -Value 1
    Enable-NetFirewallRule -DisplayGroup 'Remote Desktop'
    Ok 'RDP enabled (NLA required)'
}

# ------------------------------------------------- qemu-ga + virtio tools
# The guest agent is what lets the Linux side resolve this VM's address
# instead of hardcoding it. Find the virtio-win CD by volume label rather than
# assuming a drive letter.
$cd = Get-Volume | Where-Object { $_.FileSystemLabel -like 'virtio-win*' } |
      Select-Object -First 1
if ($cd) {
    $d = "$($cd.DriveLetter):"
    Say "virtio-win CD at $d"

    $ga = Get-ChildItem "$d\guest-agent\qemu-ga-x86_64.msi" -ErrorAction SilentlyContinue
    if ($ga) {
        Start-Process msiexec.exe -Wait -ArgumentList "/i `"$($ga.FullName)`" /quiet /norestart"
        Ok 'QEMU guest agent installed'
    } else { Warn 'qemu-ga MSI not found on CD' }

    if (Get-ChildItem "$d\virtio-win-guest-tools.exe" -ErrorAction SilentlyContinue) {
        Warn 'Run virtio-win-guest-tools.exe manually (it wants a reboot).'
    }
} else {
    Warn 'virtio-win CD not mounted - skipping guest agent.'
    Warn 'Without it, pin VM_HOST= in harness.conf on the Linux side.'
}

# ------------------------------------------------------------------ report
Say 'Summary:'
Get-Service sshd, QEMU-GA -ErrorAction SilentlyContinue |
    Format-Table Name, Status, StartType -AutoSize
Write-Host "`nReachable at:" -ForegroundColor Cyan
Get-NetIPAddress -AddressFamily IPv4 |
    Where-Object { $_.IPAddress -notlike '127.*' } |
    Select-Object IPAddress, InterfaceAlias | Format-Table -AutoSize
